(() => {
  const ID = 'stunt-ride';
  const shell = () => window.TelePlayGameShell;
  const tg = window.Telegram?.WebApp;
  let screen, bike, hint, gesture, scoreEl, running = false, paused = false, round = 0, score = 0, combo = 1, points = [], callbacks = {}, initialized = false;
  const haptic = type => { try { tg?.HapticFeedback?.impactOccurred(type); } catch (_) {} };
  function begin(event) { if (!running || paused) return; points = [{ x: event.clientX, y: event.clientY, t: performance.now() }]; gesture.textContent = 'Веди палец: петля или длинный взмах'; screen.setPointerCapture?.(event.pointerId); }
  function move(event) { if (!points.length) return; points.push({ x: event.clientX, y: event.clientY, t: performance.now() }); const last = points[points.length - 1], first = points[0]; gesture.textContent = `Жест: ${Math.floor(Math.hypot(last.x - first.x, last.y - first.y))} px`; }
  function end() { if (!points.length || !running || paused) return; const first = points[0], last = points[points.length - 1], distance = Math.hypot(last.x - first.x, last.y - first.y), vertical = first.y - last.y, complexity = Math.min(3, Math.floor(points.length / 12)); points = []; const landed = distance > 90 && vertical > 25; bike.classList.add('is-air'); setTimeout(() => bike.classList.remove('is-air'), 320); if (landed) { const trickScore = 80 + complexity * 45; score += trickScore * combo; combo = Math.min(5, combo + 1); hint.textContent = complexity > 1 ? `Трюк x${complexity}: приземление!` : 'Чистое приземление'; haptic('medium'); } else { combo = 1; score = Math.max(0, score - 45); hint.textContent = 'Краш — жест не дал устойчивого приземления'; haptic('heavy'); } round += 1; scoreEl.textContent = score; if (round >= 6) finish(); }
  function finish() { if (!running) return; running = false; const previous = shell().getStats(ID), result = shell().saveResult(ID, score, { bestCombo: Math.max(previous.bestCombo || 1, combo), lastResult: { score, round, combo } }), reward = Math.max(1, Math.floor(score / 120)); window.TelePlayCore?.RewardManager?.award(ID, { coins: reward, score, metadata: { transactionId: `game:${ID}:run:${Date.now()}`, rounds: round, maxCombo: combo } }); shell().emit('stunt_ride_finished', { gameId: ID, score, rounds: round, maxCombo: combo, reward }); shell().emit('game_finished', { gameId: ID, score, reward, rounds: round, maxCombo: combo, victory: score > 300 }); shell().ResultScreen.show(screen.querySelector('[data-stunt-result]'), { score, bestScore: result.bestScore, reward, newRecord: result.newRecord, title: score > 300 ? 'Трасса<br>пройдена!' : 'Ещё<br>попытка?', details: { rounds: `${round} / 6`, combo: `×${combo}` } }); screen.querySelector('[data-stunt-result]').hidden = false; }
  function start() { running = true; paused = false; round = 0; score = 0; combo = 1; points = []; screen.querySelector('[data-stunt-start]').hidden = true; screen.querySelector('[data-stunt-result]').hidden = true; screen.querySelector('[data-stunt-pause]').textContent = 'Ⅱ'; scoreEl.textContent = '0'; hint.textContent = 'Сделай жест для первого трюка'; gesture.textContent = 'Зона жеста готова'; shell().emit('stunt_ride_started', { gameId: ID }); shell().emit('game_started', { gameId: ID }); haptic('light'); }
  function open(options = {}) { callbacks = options; screen.hidden = false; screen.querySelector('[data-stunt-start]').hidden = false; screen.querySelector('[data-stunt-result]').hidden = true; const stats = shell().getStats(ID); screen.querySelector('[data-stunt-menu-best]').textContent = Number(stats.bestScore || 0).toLocaleString('ru-RU'); try { tg?.requestFullscreen?.(); tg?.disableVerticalSwipes?.(); } catch (_) {} }
  function hide() { running = false; points = []; screen.hidden = true; try { tg?.enableVerticalSwipes?.(); tg?.exitFullscreen?.(); } catch (_) {} }
  function close() { hide(); callbacks.onHome?.(); }
  function pause() { if (!running) return; paused = !paused; screen.querySelector('[data-stunt-pause]').textContent = paused ? '▶' : 'Ⅱ'; if (paused) points = []; hint.textContent = paused ? 'Пауза' : 'Зона жеста готова'; shell().emit(paused ? 'game_paused' : 'game_resumed', { gameId: ID }); }
  function init() { if (initialized) return; initialized = true; screen = document.getElementById('stuntRideScreen'); screen.innerHTML = `<div class="stunt-ride-inner"><header class="stunt-ride-hud"><button class="icon-button" data-stunt-close aria-label="На главную">×</button><div class="stunt-ride-brand"><small>TELEPLAY · ГОНКИ</small><b>Stunt Ride</b></div><div class="stunt-ride-stat"><small>СЧЁТ</small><b data-stunt-score>0</b></div><button class="icon-button" data-stunt-pause aria-label="Пауза">Ⅱ</button></header><div class="stunt-track"><span class="stunt-ramp"></span><span class="stunt-trail"></span><span class="stunt-bike" data-stunt-bike></span></div><p class="stunt-hint" data-stunt-hint>Создай трюк собственным жестом</p><div class="stunt-gesture" data-stunt-gesture>Зона жеста</div></div><div class="start-panel" data-stunt-start><span class="panel-kicker">TELEPLAY · ГОНКИ</span><h2>Stunt<br>Ride</h2><p>Создай движение байка жестом.<br>Приземлись и наращивай combo.</p><button class="play-button large" data-stunt-start-button>Начать заезд</button><div class="record">Лучший результат: <b data-stunt-menu-best>0</b></div></div><div class="start-panel result-panel" data-stunt-result hidden><span class="panel-kicker" data-result="kicker">ЗАЕЗД ОКОНЧЕН</span><h2 data-result="title">Трасса<br>пройдена!</h2><div class="result-score"><small>РЕЗУЛЬТАТ</small><b data-result="score">0</b></div><div class="result-details"><span>Лучший результат <b data-result="best">0</b></span><span>Получено <b data-result="reward">+0 🪙</b></span><span>Раунды <b data-result="rounds">0 / 6</b></span><span>Комбо <b data-result="combo">×1</b></span></div><button class="play-button large" data-stunt-replay>Новый заезд</button><button class="text-button" data-stunt-home>На главную</button></div>`; bike = screen.querySelector('[data-stunt-bike]'); hint = screen.querySelector('[data-stunt-hint]'); gesture = screen.querySelector('[data-stunt-gesture]'); scoreEl = screen.querySelector('[data-stunt-score]'); const zone = screen.querySelector('[data-stunt-gesture]'); zone.addEventListener('pointerdown', begin); zone.addEventListener('pointermove', move); zone.addEventListener('pointerup', end); zone.addEventListener('pointercancel', end); screen.querySelector('[data-stunt-start-button]').addEventListener('click', start); screen.querySelector('[data-stunt-replay]').addEventListener('click', start); screen.querySelector('[data-stunt-home]').addEventListener('click', close); screen.querySelector('[data-stunt-close]').addEventListener('click', close); screen.querySelector('[data-stunt-pause]').addEventListener('click', pause); document.addEventListener('visibilitychange', () => { if (document.hidden && !screen.hidden && running && !paused) pause(); }); }
  window.StuntRideGame = { init, open, hide, close, start, restart: start, pause, resume: () => { if (paused) pause(); }, destroy: hide };
  document.readyState === 'loading' ? document.addEventListener('DOMContentLoaded', init) : init();
})();
